import threading
from concurrent.futures import Future

def once_per_key(fn):
    lock = threading.Lock()
    futures = {}

    def wrapper(key):
        with lock:                      # check + register together
            fut = futures.get(key)
            owner = fut is None
            if owner:
                fut = Future()
                futures[key] = fut
        if owner:                       # compute outside the lock
            try:
                fut.set_result(fn(key))
            except Exception as e:
                fut.set_exception(e)
        return fut.result()             # waiters block here
    return wrapper
